/**
 * A measured value in a known range (`design/components/meter.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/meter.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import { Icon, MEMBER_PROVIDERS, derived, useMember, type IconProps } from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/meter.module.css'

export interface MeterMessages {
  /** The glyph's name past `warning`: "High". */
  warning: string
  /** The glyph's name past `danger`: "Critical". */
  danger: string
}

/** A measured value in a known range: the inputs it takes, by the React member's prop names. */
export interface MeterProps {
  /**
   * From this value up, the meter is in its danger band.
   */
  danger?: number
  /**
   * Required, because an unnamed meter tells a screen reader nothing.
   */
  label: string
  /**
   * The top of the range: the limit, the quota, the budget.
   */
  max?: number
  /**
   * The status glyph's names. English when omitted.
   */
  messages?: MeterMessages
  /**
   * The bottom of the range.
   */
  min?: number
  /**
   * The measured value, in the range's units. It is drawn clamped to `min`–`max`.
   */
  value: number
  /**
   * The value in the app's words, seen under the bar and heard as the meter's value.
   */
  valueText?: string
  /**
   * From this value up, the meter is in its warning band.
   */
  warning?: number
}

/** A measured value in a known range. */
@Component({
  selector: 'pm-meter',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Icon],
  // prettier-ignore
  template: `<!-- meter -->
<div
[attr.class]="e1()"
[attr.data-tone]="e2()"
data-member="meter"
><!-- track -->
<div
[attr.class]="e3()"
role="meter"
[attr.aria-label]="e4()"
[attr.aria-valuenow]="e5()"
[attr.aria-valuemin]="e6()"
[attr.aria-valuemax]="e7()"
[attr.aria-valuetext]="e8()"
><!-- fill -->
<div
[attr.class]="e9()"
[style.transform]="e10()"
></div></div>
@if (e11()) {<!-- readout -->
<div
[attr.class]="e12()"
>@if (e13()) {<!-- status -->
<span
[attr.class]="e14()"
><pm-icon
[name]="e15()"
size="sm"
[label]="e16()"
></pm-icon></span>}
@if (e17()) {<!-- value -->
<span
[attr.class]="e18()"
aria-hidden="true"
>{{ e19() }}</span>}</div>}</div>`,
})
export class Meter {
  /**
   * From this value up, the meter is in its danger band.
   */
  readonly danger = input<MeterProps['danger']>(undefined)
  /**
   * Required, because an unnamed meter tells a screen reader nothing.
   */
  readonly label = input.required<MeterProps['label']>()
  /**
   * The top of the range: the limit, the quota, the budget.
   */
  readonly max = input<Exclude<MeterProps['max'], undefined>, MeterProps['max']>(100, {
    transform: (value: MeterProps['max']) => (value === undefined ? 100 : value),
  })
  /**
   * The status glyph's names. English when omitted.
   */
  readonly messages = input<Exclude<MeterProps['messages'], undefined>, MeterProps['messages']>(
    (() => ({ warning: 'High', danger: 'Critical' }))(),
    {
      transform: (value: MeterProps['messages']) =>
        value === undefined ? (() => ({ warning: 'High', danger: 'Critical' }))() : value,
    },
  )
  /**
   * The bottom of the range.
   */
  readonly min = input<Exclude<MeterProps['min'], undefined>, MeterProps['min']>(0, {
    transform: (value: MeterProps['min']) => (value === undefined ? 0 : value),
  })
  /**
   * The measured value, in the range's units. It is drawn clamped to `min`–`max`.
   */
  readonly value = input.required<MeterProps['value']>()
  /**
   * The value in the app's words, seen under the bar and heard as the meter's value.
   */
  readonly valueText = input<MeterProps['valueText']>(undefined)
  /**
   * From this value up, the meter is in its warning band.
   */
  readonly warning = input<MeterProps['warning']>(undefined)
  protected readonly $ = useMember({
    events: [],
    props: {
      danger: () => this.danger(),
      label: () => this.label(),
      max: () => this.max(),
      messages: () => this.messages(),
      min: () => this.min(),
      value: () => this.value(),
      valueText: () => this.valueText(),
      warning: () => this.warning(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly shown = derived(() =>
    Math.min(this.$p.max, Math.max(this.$p.min, this.$p.value)),
  )
  protected readonly ratio = derived(() =>
    this.$p.max > this.$p.min ? (this.shown.value - this.$p.min) / (this.$p.max - this.$p.min) : 0,
  )
  protected readonly tone = derived(() =>
    this.$p.danger !== undefined && this.$p.value >= this.$p.danger
      ? 'danger'
      : this.$p.warning !== undefined && this.$p.value >= this.$p.warning
        ? 'warning'
        : 'accent',
  )

  protected e1() {
    return styles.meter
  }

  protected e2() {
    return this.tone.value
  }

  protected e3() {
    return styles.track
  }

  protected e4() {
    return this.$p.label
  }

  protected e5() {
    return this.shown.value
  }

  protected e6() {
    return this.$p.min
  }

  protected e7() {
    return this.$p.max
  }

  protected e8() {
    return this.$p.valueText
  }

  protected e9() {
    return styles.fill
  }

  protected e10() {
    return `scaleX(${this.ratio.value})`
  }

  protected e11() {
    return this.tone.value !== 'accent' || this.$p.valueText !== undefined
  }

  protected e12() {
    if (!(this.tone.value !== 'accent' || this.$p.valueText !== undefined))
      return undefined as never
    return styles.readout
  }

  protected e13() {
    if (!(this.tone.value !== 'accent' || this.$p.valueText !== undefined))
      return undefined as never
    return this.tone.value !== 'accent'
  }

  protected e14() {
    if (!(this.tone.value !== 'accent' || this.$p.valueText !== undefined))
      return undefined as never
    if (!(this.tone.value !== 'accent')) return undefined as never
    return styles.status
  }

  protected e15(): IconProps['name'] {
    if (!(this.tone.value !== 'accent' || this.$p.valueText !== undefined))
      return undefined as never
    if (!(this.tone.value !== 'accent')) return undefined as never
    return this.tone.value === 'danger' ? 'error' : 'warning'
  }

  protected e16(): IconProps['label'] {
    if (!(this.tone.value !== 'accent' || this.$p.valueText !== undefined))
      return undefined as never
    if (!(this.tone.value !== 'accent')) return undefined as never
    return this.tone.value === 'danger' ? this.$p.messages.danger : this.$p.messages.warning
  }

  protected e17() {
    if (!(this.tone.value !== 'accent' || this.$p.valueText !== undefined))
      return undefined as never
    return this.$p.valueText !== undefined
  }

  protected e18() {
    if (!(this.tone.value !== 'accent' || this.$p.valueText !== undefined))
      return undefined as never
    if (!(this.$p.valueText !== undefined)) return undefined as never
    return styles.value
  }

  protected e19() {
    if (!(this.tone.value !== 'accent' || this.$p.valueText !== undefined))
      return undefined as never
    if (!(this.$p.valueText !== undefined)) return undefined as never
    return this.$p.valueText
  }
}
